INSERT INTO public.sgc_casos VALUES (3482, '2024-06-27', '22504334', 'JEYNNER ', 'SERRADA ', '04120135967', 'No Aplica', 1, 3, 18, 14, 181, 617, 2, 'En fecha 23 de febrero de 2023 actuando en mi condición de apoderado ante el SAPI de Lavanderia y Tintoreria quick press CA. RIF J-30390273-1, solicité formalmente el registro de una marca en su clase internacional 47 denominada TINTORERIA BIOETICA, quedando registrada dicha solicitud bajo el numero 2023-001199, la cual fue devuelta por defecto de forma en el boletín en el boletín 622, siendo subsanados dichos defectos de forma en los dias posteriores, ahora bien, en fecha 14 de noviembre de 2023 por no tener ningún avance en el tramite ni su estatus consigné en la taquilla del SAPI un escrito de agilización de tramite dirigido al registrador de la propiedad Industrial, sin tener ninguna respuesta o cambios en el estatus del tramite de registro. es el caso que después de mas de un año de haber sido el prenombrado boletín 622 del SAPI, no he recibido ningún avance en el proceso solicitado por lo cual solicito muy respetuosamente se haga efectiva la continuidad del proceso de registro de la marca mencionada. sin mas a que referirme me despido esperando una respuesta oportuna. ', 6, 1, 'V', false, 1, 'No aplica', 'jeynnerserrada@gmail.com', 1, '15:27:07 PM', NULL, NULL);
