INSERT INTO public.sgc_casos VALUES (4126, '2024-07-17', '14020917', 'MARLIN ', 'LINARES', '04142247701', 'No Aplica', 1, 3, 18, 14, 183, 621, 2, 'Debemos renovar la marca DIAMOND SEAL NO. 2008-016014, el 28 de julio del presente año 2024, y la misma no tiene número de registro asignado, ya que cuando fue concedida en el Boletín 505 y se pagaron los derechos, fue interpuesta un Nulidad Absoluta contra el acto administrativo de concesión, pero dicha Nulidad no fue ratificada en el Boletín 588, por lo cual quedó perimido de acuerdo con lo indicado en la WEBPI en la cronología de eventos de la marca en cuestión en fecha 20/12/2019. Es por ello, que solicitamos nos sea asignado el número de registro correspondiente ya que no podemos avanzar con la solicitud de renovación virtual, siendo que os exige dicho número. . Agradecemos la urgente atención al caso considerando la pronta fecha de renovación 28 de julio de 2024. Saludos cordiales,', 6, 2, 'V', false, 1, 'No aplica', 'MLINARES@CLARKEMODET.COM', 1, '14:50:46 PM', NULL, NULL);
